func TestOAuthLoginSuccessDescribesOnlyReturnedScopes(t *testing.T) {
	for _, test := range []struct{ name, response, message string }{
		{"omitted", "{}", "Connected successfully."},
		{"empty", "{\"scope\":\"\"}", "Connected successfully."},
		{"whitespace", "{\"scope\":\"   \"}", "Connected successfully."},
		{"granted", "{\"scope\":\"stores:read products:read\"}", "Granted scopes: stores:read products:read."},
	} {
		t.Run(test.name, func(t *testing.T) {
			var pair oauthPair
			if err := json.Unmarshal([]byte(test.response), &pair); err != nil {
				t.Fatal(err)
			}
			var output strings.Builder
			if err := writeOAuthLoginSuccess(&output, "default", pair.Scope); err != nil {
				t.Fatal(err)
			}
			want := "Saved OAuth profile default. " + test.message + " Select a store with stores use after listing accessible stores.\n"
			if output.String() != want {
				t.Fatalf("unexpected login message: %q", output.String())
			}
		})
	}
}
func TestAuthorizationURLCanBeCopiedWithoutJSONDecoding(t *testing.T) {
	address := "https://example.com/oauth/authorize?client_id=public-client&code_challenge=challenge&code_challenge_method=S256&redirect_uri=http%3A%2F%2F127.0.0.1%3A42189%2Fcallback&response_type=code&scope=stores%3Aread+products%3Aread&state=random-state"
	var output strings.Builder
	if err := writeAuthorizationURL(&output, address); err != nil {
		t.Fatal(err)
	}
	raw := output.String()
	if strings.Count(raw, "\n") != 1 {
		t.Fatal("expected one JSONL event")
	}
	var event map[string]any
	if err := json.Unmarshal([]byte(raw), &event); err != nil {
		t.Fatal(err)
	}
	if event["type"] != "authorization_url" || event["url"] != address || event["timeout_seconds"] != float64(300) {
		t.Fatal("authorization event changed")
	}
	_, tail, ok := strings.Cut(raw, "\"url\":\"")
	if !ok {
		t.Fatal("missing URL")
	}
	copied, _, ok := strings.Cut(tail, "\"")
	if !ok || copied != address {
		t.Fatal("printed URL requires JSON decoding")
	}
	parsed, err := url.Parse(copied)
	if err != nil {
		t.Fatal(err)
	}
	for key, want := range map[string]string{"client_id": "public-client", "code_challenge": "challenge", "code_challenge_method": "S256", "state": "random-state", "scope": "stores:read products:read", "redirect_uri": "http://127.0.0.1:42189/callback"} {
		if parsed.Query().Get(key) != want {
			t.Fatalf("missing or altered %s", key)
		}
	}
}
