func TestOAuthDiagnosticsRedactProviderBodies(t *testing.T) {
	for _, code := range []string{"access_denied", "invalid_client", "invalid_scope", "invalid_grant", "private-token"} {
		t.Run(code, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.WriteHeader(400)
				_ = json.NewEncoder(w).Encode(map[string]string{"error": code, "error_description": "private-token", "refresh_token": "private-token"})
			}))
			defer server.Close()
			err := oauthPost(context.Background(), server.URL, "/oauth/token", url.Values{}, nil)
			detail := FormatError(err)
			if strings.Contains(detail, "private-token") {
				t.Fatal("provider response leaked")
			}
			if code != "private-token" && !strings.Contains(detail, code) {
				t.Fatal("missing diagnostic category", detail)
			}
			if (code == "invalid_client" || code == "invalid_scope") && strings.Contains(detail, "authorize again") {
				t.Fatal("configuration failure suggested reauthorization")
			}
		})
	}
}
